(x, y, t) => {
  const cx = 240, cy = 120;
  let wx = Math.sin(x * 0.018 + t * 0.3) * 18 + Math.cos(y * 0.012 - t * 0.22) * 12;
  let wy = Math.cos(y * 0.018 - t * 0.28) * 18 + Math.sin(x * 0.015 + t * 0.32) * 12;
  wx += Math.sin((x + y) * 0.008 + t * 0.15) * 8;
  wy += Math.cos((x - y) * 0.008 - t * 0.18) * 8;
  const sx = x + wx, sy = y + wy;
  let wx2 = Math.sin(sx * 0.025 - t * 0.4) * 10 + Math.cos(sy * 0.02 + t * 0.35) * 8;
  let wy2 = Math.cos(sy * 0.025 + t * 0.45) * 10 + Math.sin(sx * 0.022 - t * 0.38) * 8;
  const sx2 = sx + wx2, sy2 = sy + wy2;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+1)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+2)*60, 220+Math.sin(t*0.75+4)*40, 0.075, 2.4, 1.05]
  ];
  let aS = 0, iS = 0, aS2 = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const d2 = Math.sqrt((sx2-sX)**2 + (sy2-sY)**2);
    aS += Math.sin(d*f - t*sp) * w;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * w;
    aS2 += Math.sin(d2*f*0.85 - t*sp*0.8 + 0.7) * w * 0.6;
  }
  const nw = src.length;
  const act = aS/nw, inh = iS/nw, act2 = aS2/nw;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx2*0.035+sy2*0.04-t*0.9)*0.15;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2)
    + Math.sin(dist*0.03-ang*5+t*0.8))*0.3;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.3 + spiral + act2*0.3)*2.0);
  const lap = Math.sin(sx2*0.16)*Math.sin(sy2*0.16) + Math.sin((sx2-sy2)*0.11+t*0.7)*0.4
    + Math.sin((sx2+sy2)*0.08-t*1.2)*0.3;
  const cell = Math.tanh(lap*1.4)*0.3;
  const ridge = Math.abs(Math.sin(dist*0.08 - ang*2 + t*0.5)) < 0.08 ? 0.15 : 0;
  const glow = Math.max(0, Math.sin(reaction*Math.PI))**3 * 0.4;
  const blend = reaction*0.6 + cell*0.2 + ridge + glow;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,45],[10,35,85],[15,65,120],[20,110,140],[40,155,135],
    [120,185,110],[195,200,80],[220,175,60],[215,130,55],
    [195,85,65],[160,50,70],[100,30,65],[50,18,55],[5,12,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75 + Math.sin(reaction*Math.PI)*0.25;
  const edge = Math.abs(reaction)>0.72 ? 1.18 : Math.abs(reaction)>0.5 ? 1.05 : 0.92;
  const g = glow * 40;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + g*0.5)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + g*0.7)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + g)|0)
  ];
}
